// Define the parallel work here. Each task gets its own worktree + branch.
// `verify` is a shell command run inside that worktree (tests/build/lint).
return [{ json: {
  repo: 'repo',            // path under workspace/ that is a git repo
  base: 'main',           // branch each worktree forks from
  clean: true,            // re-runnable: wipe same-id worktrees/branches first
  tasks: [
    { id: 'bump-deps',   prompt: 'Upgrade dependencies with security advisories; keep tests green.', verify: 'npm test' },
    { id: 'fix-lint',    prompt: 'Fix all lint errors without changing behavior.',                   verify: 'npm run lint' },
    { id: 'add-tests',   prompt: 'Add unit tests for the untested utils in src/lib.',                verify: 'npm test' }
  ]
} }];

// Turn the runner's results into a review summary. Feed `message` into the
// Notify sub-workflow if you want an alert.
const r = $input.first().json;
const lines = (r.results || []).map(x =>
  `- ${x.id} [${x.status}]` +
  (x.verify ? ` verify:${x.verify.passed ? 'PASS' : 'FAIL'}` : '') +
  (x.diffStat ? ` (${x.diffStat.replace(/\n/g,' ')})` : '')
);
return [{ json: {
  severity: (r.results || []).some(x => x.status === 'failed' || x.status === 'error') ? 'warn' : 'info',
  title: 'Parallel fan-out complete',
  message: `${r.review}\n\n${lines.join('\n')}`,
  source: 'parallel-fanout'
} }];
